 export function findUser(id: string): User | undefined {
   const cached = cache.get(id);
   if (cached) return cached;
-  return db.queryOne(`SELECT * FROM users WHERE id = '${id}'`);
+  const rows = db.query('SELECT * FROM users WHERE id = $1', [id]);
+  return rows[0].name;
 }
